"""Errors raised by the stockroom library."""


class ParseError(ValueError):
    """A mistake in one of the data files.

    ``line`` is the 1-based line number (blank and comment lines count) and
    ``reason`` the human-readable explanation; ``str(error)`` is
    ``"line N: reason"``.  The library does not know file names.
    """

    def __init__(self, line, reason):
        self.line = line
        self.reason = reason
        super().__init__("line %d: %s" % (line, reason))

    def __reduce__(self):
        return (ParseError, (self.line, self.reason))
