"""Shared text handling: line splitting and strict token parsers."""

import decimal
import re
from datetime import date
from decimal import Decimal

BOM = "﻿"

# Exact arithmetic: every rounding step is explicit, so give the context room
# for any number the files can hold.
CTX = decimal.Context(
    prec=500000,
    rounding=decimal.ROUND_HALF_UP,
    Emax=decimal.MAX_EMAX,
    Emin=decimal.MIN_EMIN,
)
PENNY = Decimal("0.01")
ZERO = Decimal("0.00")

SEPARATOR = re.compile(r"[ \t]+")
_PRICE = re.compile(r"[0-9]+(?:\.[0-9]{1,2})?")
_UNSIGNED = re.compile(r"[0-9]+")
_SIGNED = re.compile(r"[+-]?[0-9]+")
_SKU = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
_ORDER_ID = re.compile(r"[Ss][Oo]-[0-9]+")
_DATE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")

_UPPER = {c: c - 32 for c in range(ord("a"), ord("z") + 1)}
_LOWER = {c: c + 32 for c in range(ord("A"), ord("Z") + 1)}


def ascii_upper(text):
    return text.translate(_UPPER)


def ascii_lower(text):
    return text.translate(_LOWER)


def trim(text):
    """Strip spaces and tabs only."""
    return text.strip(" \t")


def content_lines(text):
    """Yield ``(line_number, stripped_line)`` for every non-blank, non-comment line.

    One leading BOM is dropped; lines end only at LF, and one CR before the
    LF is removed.  Skipped lines still count towards the numbering.
    """
    if text.startswith(BOM):
        text = text[1:]
    for number, raw in enumerate(text.split("\n"), 1):
        if raw.endswith("\r"):
            raw = raw[:-1]
        line = trim(raw)
        if not line or line[0] == "#":
            continue
        yield number, line


def to_int(digits):
    """int() of an already validated ASCII digit string, however long."""
    try:
        return int(digits)
    except ValueError:  # beyond the interpreter's str->int digit limit
        return int(CTX.create_decimal(digits))


def money(value):
    """Quantize to the penny (halves up)."""
    return value.quantize(PENNY, rounding=decimal.ROUND_HALF_UP, context=CTX)


def format_money(value):
    """Two decimals, a leading minus when negative, zero never signed."""
    if value == 0:
        return "0.00"
    return format(value, "f")


def parse_price(token):
    """Decimal price from text, or None when it breaks the rules."""
    if not _PRICE.fullmatch(token):
        return None
    value = CTX.create_decimal(token)
    if value < PENNY:
        return None
    return money(value)


def parse_unsigned(token):
    """int from ``[0-9]+`` text, or None."""
    if not _UNSIGNED.fullmatch(token):
        return None
    return to_int(token)


def parse_signed(token):
    """int from ``[+-]?[0-9]+`` text, or None."""
    if not _SIGNED.fullmatch(token):
        return None
    return to_int(token)


def parse_sku(token):
    """Upper-cased SKU, or None when the shape is wrong."""
    if not _SKU.fullmatch(token):
        return None
    return ascii_upper(token)


def parse_order_id(token):
    """Upper-cased order id (digits kept as written), or None."""
    if not _ORDER_ID.fullmatch(token):
        return None
    return ascii_upper(token)


def parse_date(token):
    """datetime.date from ``YYYY-MM-DD`` text, or None (bad shape or not a real day)."""
    match = _DATE.fullmatch(token)
    if not match:
        return None
    try:
        return date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
    except ValueError:
        return None
EOF
